SourceCode.Declaration:
/// <summary>
/// Data contract class for sales picking list generation service task
/// </summary>
[DataContractAttribute]
class METSalesPickingListGenerationTaskContract
{
    container       oscCodeList;
    SalesId         salesId;

}

Method.Source:
    /// <summary>
    /// OSCCode list which contains the list of OSCCode need to be processed
    /// </summary>
    /// <param name = "_oscCodeList">OSCCode list</param>
    /// <returns>OSCCode list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmOSCCodeList(container _oscCodeList = oscCodeList)
    {
        oscCodeList = _oscCodeList;

        return oscCodeList;
    }

    /// <summary>
    /// Sales Id which need to be processed
    /// </summary>
    /// <param name = "_salesId">Sales Id</param>
    /// <returns>Sales Id</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public SalesId parmSalesId(SalesId _salesId = salesId)
    {
        salesId = _salesId;

        return salesId;
    }

    /// <summary>
    /// get Caption for the batch job task based on sales id and OSC code
    /// </summary>
    /// <returns>batch job caption</returns>
    public str getCaption()
    {
        int i;
        str caption = strFmt('%1 - ', this.parmSalesId());

        for(i = 1; i <= conLen(this.parmOSCCodeList()); i++)
        {
            if(i != 1)
            {
                caption += ', ';                
            }
            caption += conPeek(this.parmOSCCodeList(), i);
        }
        return caption;
    }
